def create_shop_orders(apps, schema_editor):
    Order = apps.get_model('orders', 'Order')
    OrderItem = apps.get_model('orders', 'OrderItem')
    ShopOrder = apps.get_model('orders', 'ShopOrder')
    ShopOrderHistory = apps.get_model('orders', 'ShopOrderHistory')

    item_states = {
        'PENDING': 'PENDING',
        'AWAITING_PAYMENT': 'PENDING',
        'COMFIRMED': 'PROCESSING',
        'PROCESSING': 'PROCESSING',
        'SHIPPING': 'SHIPPING',
        'DELIVERED': 'COMPLETED',
        'COMPLETED': 'COMPLETED',
        'CANCELLED': 'CANCELLED',
        'RETURNED': 'COMPLETED',
    }
    ranks = {
        'PENDING': 0,
        'PROCESSING': 1,
        'SHIPPING': 2,
        'DELIVERED': 3,
        'COMPLETED': 4,
        'CANCELLED': 5,
    }

    grouped = (
        OrderItem.objects.order_by()
        .values('order_id', 'shop_id')
        .distinct()
    )
    for pair in grouped.iterator():
        order = Order.objects.get(pk=pair['order_id'])
        legacy_statuses = list(OrderItem.objects.filter(
            order_id=pair['order_id'],
            shop_id=pair['shop_id'],
        ).values_list('item_status', flat=True))
        statuses = [item_states.get(status, 'PENDING') for status in legacy_statuses]
        active_statuses = [status for status in statuses if status != 'CANCELLED']
        status = (
            min(active_statuses, key=lambda value: ranks[value])
            if active_statuses
            else 'CANCELLED'
        )
        shop_order = ShopOrder.objects.create(
            order_id=pair['order_id'],
            shop_id=pair['shop_id'],
            status=status,
            confirmation_deadline=order.created_at + timedelta(hours=12),
        )
        ShopOrderHistory.objects.create(
            shop_order_id=shop_order.pk,
            old_status='',
            new_status=status,
            note='Khởi tạo trạng thái phần hàng từ dữ liệu đơn cũ.',
        )

    ranks = {
        'PENDING': 0,
        'PROCESSING': 1,
        'SHIPPING': 2,
        'DELIVERED': 3,
        'COMPLETED': 4,
    }
    for order in Order.objects.all().iterator():
        new_status = {
            'AWAITING_PAYMENT': 'PENDING',
            'COMFIRMED': 'PROCESSING',
            'DELIVERED': 'COMPLETED',
        }.get(order.order_status, order.order_status)
        suborder_statuses = list(
            ShopOrder.objects.filter(order_id=order.pk).values_list('status', flat=True)
        )
        if suborder_statuses and new_status != 'RETURNED':
            active = [status for status in suborder_statuses if status != 'CANCELLED']
            new_status = (
                min(active, key=lambda value: ranks[value])
                if active else 'CANCELLED'
            )
        if new_status != order.order_status:
            Order.objects.filter(pk=order.pk).update(order_status=new_status)


